import * as THREE from 'three';
import {configureSourceTangentMaterial,injectSourceTangentFrame,sourceTangentProgramKey} from './source-tangent-frame.js';

// Generated by tools/materials/metalonly-prepare.py. Source material math and
// renderer mappings are deliberately recorded separately in the asset document.
export const METALONLY_GLSL = __METALONLY_GLSL__;
const ROLES = ['globalWear','wear','normalAO','grunge','metalCS','metalNormal','aluminium'];

export async function prepareRecoveredMetalOnlyMaterials(document, manager) {
  if (!document?.materials?.length) return { apply() {}, applied: 0, provenance: null };
  const loader = new THREE.TextureLoader(manager), textures = new Map();
  const sources = new Map(Object.values(document.sourceTextures).map(row => [row.url, row]));
  const urls = [...new Set(document.materials.flatMap(row => Object.values(row.textures)))];
  // Bound decoder work while loading the shared textures once per document.
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(4, urls.length) }, async () => {
    while (next < urls.length) {
      const url = urls[next++], source = sources.get(url);
      if (!source) throw new Error(`Missing MetalOnly texture provenance: ${url}`);
      const texture = await loader.loadAsync(url);
      texture.colorSpace = source.colorSpace === 'srgb' ? THREE.SRGBColorSpace : THREE.NoColorSpace;
      texture.flipY = false;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.minFilter = THREE.LinearMipmapLinearFilter;
      texture.magFilter = THREE.LinearFilter;
      textures.set(url, texture);
    }
  }));
  const recipes = new Map(document.materials.map(row => [`${row.assetId}/${row.materialId}`, row]));
  let applied = 0;
  return {
    provenance: { evidenceId: document.evidenceId, sections: recipes.size, textures: textures.size, runtimeMapping: document.runtimeMapping, limitations: document.limitations },
    get applied() { return applied; },
    apply(gltf, asset) {
      gltf.scene.traverse(mesh => {
        if (!mesh.isMesh) return;
        for (const material of [].concat(mesh.material)) {
          if (material.userData.recoveredMetalOnlyShader) continue;
          const recipe = recipes.get(`${asset.id}/${material.userData.sourceMaterialId}`);
          if (!recipe) continue;
          if (!mesh.geometry.getAttribute('uv')) throw new Error(`Source MetalOnly mesh has no UV0: ${asset.id}/${recipe.materialId}`);
          material.color.setRGB(1, 1, 1);
          material.roughness = 1;
          // Native ID0 uses o2.y as metalness and o2.z=.5 as dielectric reflectance.
          // The shader hook below supplies the source per-pixel metalness.
          material.metalness = 0;
          material.map = material.normalMap = material.roughnessMap = material.metalnessMap = material.aoMap = material.emissiveMap = null;
          material.emissive?.setRGB(0, 0, 0);
          material.userData.recoveredMetalOnlyShader = { evidenceId: document.evidenceId, sourceShader: recipe.sourceShader, runtimeMapping: document.runtimeMapping };
          material.userData.placeholder = false;
          material.userData.neutralColorApproximation = false;
          configureSourceTangentMaterial(material,mesh.geometry);
          material.onBeforeCompile = function(shader) {
            for (const role of ROLES) shader.uniforms[`bf2_metalonly_${role}`] = { value: textures.get(recipe.textures[role]) };
            shader.uniforms.bf2_metalonly_cb = { value: recipe.constants.map(v => new THREE.Vector4(...v)) };
            shader.vertexShader = `varying vec2 bf2_metalonly_uv;
              varying vec3 bf2_metalonly_world;
              varying vec3 bf2_metalonly_geometricNormal;
            ` + shader.vertexShader;
            shader.vertexShader = shader.vertexShader.replace('#include <worldpos_vertex>', `#include <worldpos_vertex>
              vec4 bf2_metalonly_wp = vec4(transformed, 1.0);
              #ifdef USE_INSTANCING
                bf2_metalonly_wp = instanceMatrix * bf2_metalonly_wp;
              #endif
              bf2_metalonly_world = (modelMatrix * bf2_metalonly_wp).xyz;
              bf2_metalonly_geometricNormal = inverseTransformDirection(transformedNormal, viewMatrix);
              bf2_metalonly_uv = uv;
            `);
            shader.fragmentShader = `varying vec2 bf2_metalonly_uv;
              varying vec3 bf2_metalonly_world;
              varying vec3 bf2_metalonly_geometricNormal;
              uniform vec4 bf2_metalonly_cb[5];
              ${ROLES.map(role => `uniform sampler2D bf2_metalonly_${role};`).join('\n')}
              ${METALONLY_GLSL}
              // Exact source-sidecar geometry selects its native frame below.
              // Uncovered source layouts retain this derivative frame.
              mat3 bf2_metalonly_tbn(vec3 position, vec3 n, vec2 uvValue) {
                vec3 q0 = dFdx(position), q1 = dFdy(position);
                vec2 st0 = dFdx(uvValue), st1 = dFdy(uvValue);
                vec3 q1perp = cross(q1, n), q0perp = cross(n, q0);
                vec3 tangent = q1perp * st0.x + q0perp * st1.x;
                vec3 bitangent = q1perp * st0.y + q0perp * st1.y;
                float invmax = inversesqrt(max(max(dot(tangent, tangent), dot(bitangent, bitangent)), 1e-16));
                return mat3(tangent * invmax, bitangent * invmax, n);
              }
            ` + shader.fragmentShader;
            shader.fragmentShader = shader.fragmentShader.replace('#include <color_fragment>', `#include <color_fragment>
              MetalOnlySurface bf2_metalonly_surface = sampleMetalOnly(bf2_metalonly_uv, bf2_metalonly_world,
                bf2_metalonly_geometricNormal, bf2_metalonly_cb,
                ${ROLES.map(role => `bf2_metalonly_${role}`).join(', ')});
              diffuseColor.rgb = bf2_metalonly_surface.color;
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
              roughnessFactor = 1.0 - clamp(bf2_metalonly_surface.smoothness, 0.0, 1.0);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <metalnessmap_fragment>', `#include <metalnessmap_fragment>
              metalnessFactor = clamp(bf2_metalonly_surface.materialScalar, 0.0, 1.0);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <normal_fragment_maps>', `
              mat3 bf2_metalonly_frame = bf2_metalonly_tbn(-vViewPosition, normal, bf2_metalonly_uv);
              normal = normalize(bf2_metalonly_frame * bf2_metalonly_surface.tangentNormal);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <aomap_fragment>', `#include <aomap_fragment>
              reflectedLight.indirectDiffuse *= bf2_metalonly_surface.ao;
            `);
            injectSourceTangentFrame(shader,this,'metalonly');
          };
          material.customProgramCacheKey = function(){return 'bf2-source-SS_DSI_Master_1UV_MetalOnly_01-85476b5805-v2|' + sourceTangentProgramKey(this);};
          material.needsUpdate = true;
          applied++;
        }
      });
    },
  };
}
